cd /workspace/submission && grep -n "MILLION" crosscheck/*.py; echo ---; python3 -m py_compile crosscheck/*.py main.py && echo COMPILES; python3 - <<'EOF'
import ast, sys, pathlib
for p in sorted(pathlib.Path('/workspace/submission').rglob('*.py')):
    tree = ast.parse(p.read_text())
    src = p.read_text()
    # crude unused-import check
    imported = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported.append(a.asname or a.name)
        elif isinstance(node, ast.Import):
            for a in node.names:
                imported.append((a.asname or a.name).split('.')[0])
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    attrs = {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    unused = [i for i in imported if i not in names and i not in attrs]
    print(p.name, 'unused imports:', unused)
EOF
